class Gradebook:
    def __init__(self):
        self.students = set()
        self.assignments = set()
        self.assignment_max_points = {}
        self.scores = {}
    
    def add_student(self, name):
        if name in self.students:
            raise ValueError("Student already exists")
        self.students.add(name)
    
    def add_assignment(self, name, max_points):
        if name in self.assignments:
            raise ValueError("Assignment already exists")
        if not isinstance(max_points, (int, float)) or max_points <= 0:
            raise ValueError("Max points must be a positive number")
        self.assignments.add(name)
        self.assignment_max_points[name] = max_points
    
    def record(self, student, assignment, points):
        if student not in self.students:
            raise KeyError("Unknown student")
        if assignment not in self.assignments:
            raise KeyError("Unknown assignment")
        if not isinstance(points, (int, float)) or points < 0 or points > self.assignment_max_points[assignment]:
            raise ValueError("Points must be between 0 and max points")
        if student not in self.scores:
            self.scores[student] = {}
        self.scores[student][assignment] = points
    
    def score(self, student, assignment):
        if student not in self.students or assignment not in self.assignments:
            return None
        if student not in self.scores or assignment not in self.scores[student]:
            return None
        return self.scores[student][assignment]

    def percent(self, student):
        if student not in self.students:
            raise KeyError("Unknown student")
        
        if student not in self.scores:
            return None
            
        total_points = 0
        total_max_points = 0
        
        for assignment, points in self.scores[student].items():
            total_points += points
            total_max_points += self.assignment_max_points[assignment]
            
        if total_max_points == 0:
            return None
            
        return round((total_points / total_max_points) * 100, 2)

if __name__ == "__main__":
    # Test the Gradebook class
    g = Gradebook()
    
    # Test add_student
    g.add_student("Alice")
    g.add_student("Bob")
    
    try:
        g.add_student("Alice")  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass
    
    # Test add_assignment
    g.add_assignment("Homework 1", 100)
    g.add_assignment("Quiz 1", 25)
    
    try:
        g.add_assignment("Homework 1", 100)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass
    
    try:
        g.add_assignment("Test 1", -5)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass
    
    try:
        g.add_assignment("Test 2", 0)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass
    
    # Test record
    g.record("Alice", "Homework 1", 85)
    g.record("Bob", "Homework 1", 92)
    g.record("Alice", "Quiz 1", 22)
    
    try:
        g.record("Charlie", "Homework 1", 80)  # Should raise KeyError
        assert False, "Should have raised KeyError"
    except KeyError:
        pass
    
    try:
        g.record("Alice", "Test 1", 80)  # Should raise KeyError
        assert False, "Should have raised KeyError"
    except KeyError:
        pass
    
    try:
        g.record("Alice", "Homework 1", -5)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass
    
    try:
        g.record("Alice", "Homework 1", 105)  # Should raise ValueError
        assert False, "Should have raised ValueError"
    except ValueError:
        pass
    
    # Test score
