            category_max_points[category] += self.assignment_max_points[assignment]

        # Calculate weighted average
        total_weighted_points = 0
        total_weights = 0

        for category in category_points:
            if category_max_points[category] > 0:
                category_percentage = (category_points[category] / category_max_points[category]) * 100
                weight = self.category_weights[category]
                total_weighted_points += category_percentage * weight
                total_weights += weight

        if total_weights == 0:
            return None

        return round(total_weighted_points / total_weights, 2)
