console.log("\nFinal state:");
console.log(`Has 'a': ${cache.has("a")}`);
console.log(`Has 'b': ${cache.has("b")}`);
console.log(`Has 'c': ${cache.has("c")}`);
console.log(`Size: ${cache.size()}`);

