  overdue(today) {
    // Collect all overdue books
    const overdueBooks = [];

    // Iterate through all books and their loans
    for (const [isbn, book] of this.books.entries()) {
      for (const [member, checkoutDay] of book.loans.entries()) {
        const dueDay = checkoutDay + 14;
        const daysLate = today - dueDay;
        if (daysLate > 0) {
          overdueBooks.push({ isbn, member, daysLate });
        }
      }
    }

    // Sort by daysLate (largest first), then isbn, then member
    overdueBooks.sort((a, b) => {
      if (b.daysLate !== a.daysLate) {
        return b.daysLate - a.daysLate;
      }
      if (a.isbn !== b.isbn) {
        return a.isbn.localeCompare(b.isbn);
      }
      return a.member.localeCompare(b.member);
    });

