} catch(e) {
    console.log("Error:", e.message);
}

console.log("\nTesting 3: Empty expression");
try {
    console.log("Result:", evaluate(""));
} catch(e) {
    console.log("Error:", e.message);
}

console.log("\nTesting 4: Valid expression");
