// Cache implementation with LRU eviction and optional TTL expiry
class Cache {
  constructor(capacity, options = {}) {
    if (capacity === 0) {
      throw new Error("Capacity must be positive");
    }
    if (capacity < 0) {
      throw new Error("Capacity must be positive");
    }
    if (!Number.isInteger(capacity)) {
      throw new Error("Capacity must be an integer");
    }

    this.capacity = capacity;
    this.map = new Map();
    this.now = options.now || (() => Date.now());
    this.ttl = options.ttl || 0;
  }

  get(key) {
    const item = this.map.get(key);
    if (item === undefined) {
      return undefined;
    }

    // Check if item has expired
    if (this.ttl > 0 && this.now() - item.timestamp > this.ttl) {
      this.map.delete(key);
      return undefined;
    }

    // Move to end (most recently used)
    this.map.delete(key);
    this.map.set(key, item);
    return item.value;
  }

  has(key) {
    const item = this.map.get(key);
    if (item === undefined) {
      return false;
    }

    // Check if item has expired
    if (this.ttl > 0 && this.now() - item.timestamp > this.ttl) {
      this.map.delete(key);
      return false;
    }

    return true;
  }

  peek(key) {
    const item = this.map.get(key);
    if (item === undefined) {
      return undefined;
    }

    // Check if item has expired
    if (this.ttl > 0 && this.now() - item.timestamp > this.ttl) {
      this.map.delete(key);
      return undefined;
    }

    return item.value;
  }

  size() {
    let count = 0;
    for (const [key, item] of this.map.entries()) {
      // Check if item has expired
      if (this.ttl > 0 && this.now() - item.timestamp > this.ttl) {
        this.map.delete(key);
        continue;
      }
      count++;
    }
    return count;
  }

  keys() {
    const result = [];
    for (const [key, item] of this.map.entries()) {
      // Check if item has expired
      if (this.ttl > 0 && this.now() - item.timestamp > this.ttl) {
        this.map.delete(key);
        continue;
      }
      result.push(key);
    }
    return result;
  }

  set(key, value, options = {}) {
    const ttl = options.ttl !== undefined ? options.ttl : this.ttl;

    // If key exists, update it
    if (this.map.has(key)) {
      const item = this.map.get(key);
      item.value = value;
      item.timestamp = this.now();
      this.map.delete(key);
      this.map.set(key, item);
    } else {
      // If cache is full, remove least recently used item
      if (this.map.size >= this.capacity) {
        const firstKey = this.map.keys().next().value;
        this.map.delete(firstKey);
      }

      // Add new item
      this.map.set(key, {
        value: value,
        timestamp: this.now()
      });
    }

    return this;
  }

  delete(key) {
    return this.map.delete(key);
  }

  clear() {
    this.map.clear();
  }
}

module.exports = { Cache };
