const g4 = new Graph();
g4.add_node("a");
g4.add_node("b");
g4.add_node("c");
g4.add_edge("a", "b");
g4.add_edge("b", "c");
console.log("Simple path graph has cycle:", g4.has_cycle()); // Should be false

