    except ValueError as e:
        print(f"Test 8 passed: Correctly raised ValueError for p=101: {e}")
    except Exception as e:
        print(f"Test 8 failed: Wrong exception type: {e}")
        return False
    
    print("All tests passed!")
    return True

if __name__ == "__main__":
