console.assert(arrayCopy !== matrix1._rows, "ToArray should return a copy");

// Test error cases
let errorCaught = false;
try {
  new Matrix([]);
} catch (e) {
  errorCaught = true;
}
console.assert(errorCaught, "Should throw error for empty rows");

errorCaught = false;
try {
