  errorCaught = true;
}
console.assert(errorCaught, "Should throw error for out of bounds access");

// Test inverse method
const testInverse = () => {
  // Test 1x1 matrix
  const m1 = new Matrix([[5]]);
  const inv1 = m1.inverse();
  console.assert(inv1.equals(new Matrix([[1/5]])), "1x1 inverse test failed");
  
  // Test 2x2 matrix
