            if (token.value === '-' && (i === 0 || tokens[i-1].type === 'lparen' || tokens[i-1].type === 'op' || tokens[i-1].type === 'comma')) {
                // This is a unary minus, treat it as 'neg'
                operatorStack.push('neg');
