                while (operatorStack.length > 0 && 
                       operatorStack[operatorStack.length - 1] !== 'lparen' &&
                       (precedence[operatorStack[operatorStack.length - 1]] > precedence[token.value] ||
                        (precedence[operatorStack[operatorStack.length - 1]] === precedence[token.value] && 
